import { SAMPLE, parseBook, bookProgress, localChineseVoices, chooseVoice, SpeechPlayer } from './core.js';
const $=id=>document.getElementById(id);
const KEY='tingye-reader-v1';
let saved={};let storageOkay=true;let database=null;let bookIsSaved=true;let importing=false;
try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{};}catch{storageOkay=false;}
const preferences={rate:Math.max(.5,Math.min(2,Number(saved.rate)||1)),font:Math.max(18,Math.min(32,Number(saved.font)||22)),voice:typeof saved.voice==='string'?saved.voice:'',follow:saved.follow!==false};
const SAMPLE_ID='sample-v1';
const positions=saved.positions&&typeof saved.positions==='object'?{...saved.positions}:{};
if(saved.bookId&&saved.position&&!positions[saved.bookId])positions[saved.bookId]={position:saved.position,ended:saved.ended===true};
const library=new Map([[SAMPLE_ID,{id:SAMPLE_ID,title:'雨到窗前',text:SAMPLE,sample:true,saved:true}]]);
let book=parseBook(SAMPLE,'雨到窗前');let bookId=SAMPLE_ID;let voices=[];let preview=null;let noticeTimer=null;let windowStart=0;let renderedChapter=-1;let restoring=true;let bookMutation=0;
function showNotice(message,sticky=false){$('notice').textContent=message;$('notice').hidden=false;clearTimeout(noticeTimer);if(!sticky)noticeTimer=setTimeout(()=>{$('notice').hidden=true;},6500);}
function storageLabel(){const warning=!storageOkay||!bookIsSaved;$('storage-status').textContent=warning?'本次可閱讀，但未能儲存':'只儲存在這個瀏覽器';$('storage-status').parentElement.classList.toggle('warning',warning);}
function persist(){if(restoring)return;positions[bookId]={position:{...player.pos},ended:player.state==='ended'};try{localStorage.setItem(KEY,JSON.stringify({...preferences,bookId,positions}));storageOkay=true;}catch{storageOkay=false;}storageLabel();}
function getVoice(){try{voices=window.speechSynthesis?.getVoices()||[];}catch{voices=[];}return chooseVoice(voices,preferences.voice);}
const player=new SpeechPlayer({synth:window.speechSynthesis,Utterance:window.SpeechSynthesisUtterance,getVoice,getRate:()=>preferences.rate,onChange:renderStatus,onPosition:()=>{renderPosition();persist();},onError:showNotice});
function clearPreview(){if(preview){preview=null;try{window.speechSynthesis?.cancel();}catch{}}}
function refreshVoices(){const voice=getVoice();const local=localChineseVoices(voices);const select=$('voice-select');select.replaceChildren();for(const v of local){const o=document.createElement('option');o.value=v.voiceURI;o.textContent=`${v.name} · ${v.lang}`;select.append(o);}if(!local.length){const o=document.createElement('option');o.value='';o.textContent='暫未找到本機中文語音';select.append(o);}else{select.value=voice.voiceURI;preferences.voice=voice.voiceURI;}select.disabled=!local.length;$('preview-voice').disabled=!local.length;$('voice-button').textContent=voice?`${voice.lang.toLowerCase().includes('hk')||voice.lang.toLowerCase().startsWith('yue')?'粵語':'中文'}語音`:'選擇語音';$('voice-help').textContent=voice?'只使用瀏覽器標示為本機的中文語音。':'暫未找到本機中文語音。可先閱讀文字；查看下方說明，再按「重新尋找」。';}
function renderLibrary(){const select=$('book-select');select.replaceChildren();for(const record of library.values()){const option=document.createElement('option');option.value=record.id;option.textContent=record.sample?`${record.title}（示範）`:record.title;select.append(option);}select.value=bookId;$('library-count').textContent=`書庫 · ${library.size} 本`;}
function renderBook(){
  renderLibrary();
  $('book-title').textContent=book.title;$('book-meta').textContent=bookId==='sample-v1'?'原創短篇示範 · 約 3 分鐘':`${book.characters.toLocaleString()} 字 · 文字書`;$('chapter-count').textContent=book.chapters.length;
  $('chapter-list').replaceChildren();book.chapters.forEach((chapter,index)=>{const b=document.createElement('button');b.className='chapter-link';b.type='button';b.dataset.chapter=index;const n=document.createElement('span');n.className='chapter-index';n.textContent=String(index+1).padStart(2,'0');const t=document.createElement('span');t.textContent=chapter.title;b.append(n,t);b.addEventListener('click',()=>{seek({chapter:index,segment:0});closeChapters();});$('chapter-list').append(b);});
  renderedChapter=-1;windowStart=0;renderPosition();storageLabel();
}
function activateBook(record,bookmark=positions[record.id]){clearPreview();player.stop();book=parseBook(record.text,record.title);bookId=record.id;bookIsSaved=record.saved!==false;player.load(book,bookmark?.position);if(bookmark?.ended===true)player.emit('ended');renderBook();persist();}
function switchBook(id){const record=library.get(id);if(!record||id===bookId)return;persist();bookMutation++;activateBook(record);}
function renderPosition(){
  const pos=player.pos;const chapter=book.chapters[pos.chapter];if(!chapter)return;
  $('chapter-title').textContent=chapter.title;$('chapter-kicker').textContent=`${String(pos.chapter+1).padStart(2,'0')} / ${String(book.chapters.length).padStart(2,'0')}`;$('chapter-number').textContent=`第 ${pos.chapter+1} 章，共 ${book.chapters.length} 章`;
  [...$('chapter-list').children].forEach((b,i)=>{b.classList.toggle('active',i===pos.chapter);if(i===pos.chapter)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current');});
  if(renderedChapter!==pos.chapter||pos.segment<windowStart||pos.segment>=windowStart+80){windowStart=Math.max(0,pos.segment-15);renderText();}
  else markSegment();
  $('previous-chapter').disabled=pos.chapter===0;$('next-chapter').disabled=pos.chapter===book.chapters.length-1;$('previous-segment').disabled=pos.chapter===0&&pos.segment===0;$('next-segment').disabled=pos.chapter===book.chapters.length-1&&pos.segment===chapter.segments.length-1;
  renderStatus();
}
function renderText(){const chapter=book.chapters[player.pos.chapter];renderedChapter=player.pos.chapter;const root=$('reading-text');root.replaceChildren();let paragraph=document.createElement('p');root.append(paragraph);chapter.segments.slice(windowStart,windowStart+80).forEach((segment,i)=>{const b=document.createElement('button');b.className='segment';b.type='button';b.textContent=segment.text;b.dataset.segment=windowStart+i;b.setAttribute('aria-label',`從第 ${windowStart+i+1} 段開始：${segment.text.slice(0,20)}`);b.addEventListener('click',()=>seek({chapter:player.pos.chapter,segment:windowStart+i}));paragraph.append(b);if(segment.paragraphEnd&&i<79){paragraph=document.createElement('p');root.append(paragraph);}});$('earlier-text').hidden=windowStart===0;$('later-text').hidden=windowStart+80>=chapter.segments.length;markSegment();}
function markSegment(){const active=$('reading-text').querySelector(`[data-segment="${player.pos.segment}"]`);$('reading-text').querySelectorAll('.current').forEach(e=>{e.classList.remove('current');e.removeAttribute('aria-current');});if(active){active.classList.add('current');active.setAttribute('aria-current','true');if(preferences.follow&&['playing','loading'].includes(player.state)){const box=active.getBoundingClientRect();if(box.top<90||box.bottom>window.innerHeight-220)active.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}}}
function renderStatus(){const playing=['playing','loading'].includes(player.state);$('play-icon').hidden=playing;$('pause-icon').hidden=!playing;$('play').setAttribute('aria-label',playing?'暫停朗讀':'開始朗讀');const states={idle:'準備朗讀',loading:'正在啟動',playing:'正在朗讀',paused:'已暫停',ended:'全書讀完了'};$('player-chapter').textContent=book.chapters[player.pos.chapter]?.title||book.title;$('player-status').textContent=`${states[player.state]} · 第 ${player.pos.segment+1} / ${book.chapters[player.pos.chapter]?.segments.length||1} 段`;const progress=bookProgress(book,player.pos,player.state==='ended');$('overall-progress').textContent=`${progress}%`;$('progress-fill').style.width=`${progress}%`;persist();}
function seek(position){clearPreview();const keepPlaying=['playing','loading'].includes(player.state);player.seek(position,keepPlaying);if(!keepPlaying&&preferences.follow)$('chapter-title').scrollIntoView({block:'start',behavior:'auto'});}
function setPreferences(){document.documentElement.style.setProperty('--reading-size',`${preferences.font}px`);$('font-size').value=preferences.font;$('font-label').textContent=`${preferences.font} px`;$('rate').value=preferences.rate;$('rate-label').textContent=`${preferences.rate.toFixed(1)}×`;$('speed-button').textContent=`${preferences.rate.toFixed(1)}×`;$('auto-follow').checked=preferences.follow;persist();}
function openDialog(id){if(id==='settings-dialog')refreshVoices();$(id).showModal();}
function closeChapters(){$('sidebar-backdrop').hidden=true;document.body.classList.remove('chapters-open');}
function openChapters(){$('sidebar-backdrop').hidden=false;document.body.classList.add('chapters-open');$('chapters-close').focus();}
function dbOpen(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(new Error('unavailable'));return;}const req=indexedDB.open('tingye-library',1);req.onupgradeneeded=()=>req.result.createObjectStore('books');req.onerror=()=>reject(req.error);req.onblocked=()=>reject(new Error('blocked'));req.onsuccess=()=>resolve(req.result);});}
function dbReadAll(){return new Promise((resolve,reject)=>{const req=database.transaction('books').objectStore('books').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbWrite(value){return new Promise((resolve,reject)=>{const tx=database.transaction('books','readwrite');tx.objectStore('books').put(value,value.id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
async function importBook(text,title){if(importing)return;importing=true;$('import-paste').disabled=true;$('import-error').hidden=true;try{const parsed=parseBook(text,title);bookMutation++;const id=`book-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;const record={id,title:parsed.title,text:parsed.text,saved:false};library.set(id,record);activateBook(record);$('import-dialog').close();$('paste-text').value='';$('paste-title').value='';try{database ||= await dbOpen();await dbWrite({id,title:parsed.title,text:parsed.text});record.saved=true;bookIsSaved=true;storageLabel();showNotice('書本已加入「我的閱讀」，可隨時切換。');}catch{bookIsSaved=false;storageLabel();showNotice('書本已打開，但未能儲存。離開前請保留原始檔案。',true);}}catch(error){$('import-error').textContent=error.message||'未能匯入，請換一個文字檔再試。';$('import-error').hidden=false;}finally{importing=false;$('import-paste').disabled=false;$('book-file').value='';}}
$('play').addEventListener('click',()=>{clearPreview();refreshVoices();if(['playing','loading'].includes(player.state))player.pause();else player.play();});
$('stop').addEventListener('click',()=>{clearPreview();player.stop();});$('previous-segment').addEventListener('click',()=>{clearPreview();player.step(-1);});$('next-segment').addEventListener('click',()=>{clearPreview();player.step(1);});$('restart').addEventListener('click',()=>seek({chapter:player.pos.chapter,segment:0}));$('previous-chapter').addEventListener('click',()=>seek({chapter:player.pos.chapter-1,segment:0}));$('next-chapter').addEventListener('click',()=>seek({chapter:player.pos.chapter+1,segment:0}));
$('open-import').addEventListener('click',()=>{player.pause();clearPreview();openDialog('import-dialog');});$('open-settings').addEventListener('click',()=>openDialog('settings-dialog'));$('speed-button').addEventListener('click',()=>openDialog('settings-dialog'));$('voice-button').addEventListener('click',()=>openDialog('settings-dialog'));document.querySelectorAll('.about-open').forEach(b=>b.addEventListener('click',()=>openDialog('about-dialog')));document.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('close',clearPreview);d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
$('chapters-toggle').addEventListener('click',openChapters);$('chapters-close').addEventListener('click',closeChapters);$('sidebar-backdrop').addEventListener('click',closeChapters);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeChapters();});
$('book-select').addEventListener('change',e=>switchBook(e.target.value));
$('font-down').addEventListener('click',()=>{preferences.font=Math.max(18,preferences.font-1);setPreferences();});$('font-up').addEventListener('click',()=>{preferences.font=Math.min(32,preferences.font+1);setPreferences();});$('font-size').addEventListener('input',e=>{preferences.font=Number(e.target.value);setPreferences();});$('rate').addEventListener('input',e=>{preferences.rate=Number(e.target.value);setPreferences();});$('rate').addEventListener('change',()=>{clearPreview();player.reconfigure();});$('auto-follow').addEventListener('change',e=>{preferences.follow=e.target.checked;persist();});$('voice-select').addEventListener('change',e=>{clearPreview();preferences.voice=e.target.value;refreshVoices();persist();player.reconfigure();});$('refresh-voices').addEventListener('click',refreshVoices);
$('preview-voice').addEventListener('click',()=>{player.pause();clearPreview();refreshVoices();const voice=getVoice();if(!voice)return;try{const u=new SpeechSynthesisUtterance('放慢腳步，聽一頁故事。');u.voice=voice;u.lang=voice.lang;u.rate=preferences.rate;preview=u;u.onend=()=>{if(preview===u)preview=null;};u.onerror=()=>{if(preview===u){preview=null;showNotice('試聽未能完成，請重新選擇語音。');}};speechSynthesis.speak(u);}catch{showNotice('這個瀏覽器未能試聽語音。');}});
$('import-paste').addEventListener('click',()=>importBook($('paste-text').value,$('paste-title').value.trim()||'我的書本'));$('load-sample').addEventListener('click',()=>{switchBook(SAMPLE_ID);$('import-dialog').close();});$('book-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>20*1024*1024)throw new Error('檔案超過 20 MB，請先分成較小的文字檔。');if(!/\.(txt|md)$/i.test(file.name))throw new Error('請選擇 TXT 或純文字 Markdown 檔案。');const buffer=await file.arrayBuffer();const text=new TextDecoder($('encoding').value,{fatal:true}).decode(buffer);await importBook(text,file.name);}catch(error){$('import-error').textContent=error instanceof TypeError?'無法用這種編碼讀取。請換一種編碼，再選擇檔案。':error.message;$('import-error').hidden=false;$('book-file').value='';}});
$('earlier-text').addEventListener('click',()=>{windowStart=Math.max(0,windowStart-65);renderText();});$('later-text').addEventListener('click',()=>{windowStart=Math.min(book.chapters[player.pos.chapter].segments.length-1,windowStart+65);renderText();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){player.pause();clearPreview();persist();}else refreshVoices();});window.addEventListener('pagehide',()=>{player.pause();clearPreview();persist();});window.speechSynthesis?.addEventListener?.('voiceschanged',refreshVoices);
// Optional browser agent hooks use exactly the visible actions. No content-reading
// tool is exposed, so using the reader doesn't invite an agent to copy book text.
try{const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();Promise.resolve(context.registerTool({name:'reader_go_to_chapter',description:'Move this reader to a numbered chapter and pause reading.',inputSchema:{type:'object',properties:{chapter:{type:'integer',minimum:1}},required:['chapter'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!Number.isInteger(input?.chapter)||input.chapter<1||input.chapter>book.chapters.length)throw new Error('Invalid chapter');player.pause();seek({chapter:input.chapter-1,segment:0});return{chapter:input.chapter,state:player.state};}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}}catch{}
setPreferences();player.load(book);renderBook();refreshVoices();
(async()=>{try{database=await dbOpen();const initialMutation=bookMutation;const records=await dbReadAll();for(const record of records){if(record&&typeof record.text==='string'&&typeof record.id==='string')library.set(record.id,{...record,saved:true});}if(initialMutation!==bookMutation||bookMutation>0){renderLibrary();return;}const target=library.get(saved.bookId)||library.get(SAMPLE_ID);activateBook(target,positions[target.id]);}catch{bookIsSaved=bookId===SAMPLE_ID;if(saved.bookId&&saved.bookId!==SAMPLE_ID)showNotice('未能還原書庫，請重新匯入原始檔案。');}finally{restoring=false;persist();}})();
